_W = TypeVar('_W', bound=type[Gtk.Widget])

CLASS_NAME = 'AdwStyleDemoDialog'
PARENT = Adw.Dialog
CHILDREN = (('button_box_1', 'button_box_1'), ('entry_box_1', 'entry_box_1'), ('entry_box_2', 'entry_box_2'), ('toggle_group_box', 'toggle_group_box'), ('toggle', 'toggle'), ('label_box', 'label_box'), ('devel_switch', 'devel_switch'), ('progress_switch', 'progress_switch'))
HANDLERS = ('sidebar_forward_cb',)


class AdwStyleDemoDialogChildren:
    """The children of the AdwStyleDemoDialog template, as attributes."""

    button_box_1: Gtk.Box
    entry_box_1: Gtk.Box
    entry_box_2: Gtk.Box
    toggle_group_box: Gtk.Box
    toggle: Gtk.ToggleButton
    label_box: Gtk.Box
    devel_switch: Adw.SwitchRow
    progress_switch: Adw.SwitchRow


def template(cls: _W) -> _W:
    """Make ``cls`` the AdwStyleDemoDialog widget defined by adw-style-demo-dialog.ui."""
    if cls.__dict__.get('__gtype_name__') != CLASS_NAME:
        raise TypeError(f'{cls.__name__} must set __gtype_name__ = {CLASS_NAME!r}')
    if not issubclass(cls, PARENT):
        raise TypeError(f'{cls.__name__} must be a subclass of {PARENT.__qualname__}')
    missing = [name for name in HANDLERS if not callable(getattr(cls, name, None))]
    if missing:
        raise TypeError(f'{cls.__name__} lacks the signal handlers {", ".join(missing)}')
    for object_id, attribute in CHILDREN:
        setattr(cls, attribute, Gtk.Template.Child(object_id))
    for name in HANDLERS:
        setattr(cls, name, Gtk.Template.Callback(name)(getattr(cls, name)))
    return Gtk.Template(string=_UI)(cls)
